3	import type { Difficulty } from "../types";
4	import { isBlockHighlightsEnabled } from "../utils/config";
5	
6	const DIFFICULTY_COLORS: Record<Difficulty, string> = {
7	  trivial:  "rgba(128, 128, 128, 0.06)",
8	  standard: "rgba(100, 149, 237, 0.08)",
9	  complex:  "rgba(255, 165, 0, 0.10)",
10	  critical: "rgba(220, 53, 69, 0.12)",
11	};
12	
13	export class BlockHighlighter implements vscode.Disposable {
14	  private readonly decorationTypes: Record<Difficulty, vscode.TextEditorDecorationType>;
15	  private readonly subscriptions: vscode.Disposable[];
16	
17	  constructor(private readonly store: SegmentStore) {
18	    this.decorationTypes = {
19	      trivial:  vscode.window.createTextEditorDecorationType({ backgroundColor: DIFFICULTY_COLORS.trivial,  isWholeLine: true }),
20	      standard: vscode.window.createTextEditorDecorationType({ backgroundColor: DIFFICULTY_COLORS.standard, isWholeLine: true }),
21	      complex:  vscode.window.createTextEditorDecorationType({ backgroundColor: DIFFICULTY_COLORS.complex,  isWholeLine: true }),
22	      critical: vscode.window.createTextEditorDecorationType({ backgroundColor: DIFFICULTY_COLORS.critical, isWholeLine: true }),
23	    };
24	    this.subscriptions = [
25	      store.onDidChange((uri) => this.refreshUri(uri)),
26	      vscode.window.onDidChangeVisibleTextEditors((editors) => {
27	        for (const editor of editors) this.applyToEditor(editor);
28	      }),
29	    ];
30	  }
31	
32	  private refreshUri(uri: vscode.Uri): void {
33	    const editors = vscode.window.visibleTextEditors.filter(
34	      (e) => e.document.uri.toString() === uri.toString(),
35	    );
36	    for (const editor of editors) this.applyToEditor(editor);
37	  }
38	
39	  private applyToEditor(editor: vscode.TextEditor): void {
