1	import * as vscode from "vscode";
2	import type { Segment, Difficulty } from "../types";
3	import type { ChatMessage, LLMAdapter } from "../llm/adapter";
4	import { MalformedResponseError } from "../llm/adapter";
5	import { loadPrompt } from "../prompts/loader";
6	
7	const VALID_DIFFICULTIES = new Set<Difficulty>(["trivial", "standard", "complex", "critical"]);
8	
9	export const DEFAULT_MAX_LINES = 2000;
10	export const MIN_COVERAGE_RATIO = 0.7;
11	
12	export class FileTooLargeError extends Error {
13	  constructor(
14	    public readonly lineCount: number,
15	    public readonly maxLines: number,
16	  ) {
17	    super(
18	      `File has ${lineCount} lines; CodeWalk currently supports files up to ${maxLines} lines.`,
19	    );
20	    this.name = "FileTooLargeError";
21	  }
22	}
23	
24	export type SegmenterLogger = (message: string) => void;
25	
26	export interface SegmenterDeps {
27	  adapter: LLMAdapter;
28	  promptsDir: string;
29	  maxLines?: number;
30	  logger?: SegmenterLogger;
31	}
32	
33	interface RawSegment {
34	  label?: unknown;
35	  oneLiner?: unknown;
36	  startLine?: unknown;
37	  endLine?: unknown;
38	  difficulty?: unknown;
39	}
40	
41	interface ValidatedSegment {
42	  label: string;
43	  oneLiner: string;
44	  startLine: number;
45	  endLine: number;
46	  difficulty: Difficulty;
47	}
48	
49	interface ParseResult {
50	  segments: ValidatedSegment[];
51	  droppedCount: number;
52	}
53	
54	class ValidationFailure extends Error {}
55	
56	export async function segment(
57	  document: vscode.TextDocument,
58	  deps: SegmenterDeps,
59	): Promise<Segment[]> {
60	  const maxLines = deps.maxLines ?? DEFAULT_MAX_LINES;
61	  if (document.lineCount > maxLines) {
62	    throw new FileTooLargeError(document.lineCount, maxLines);
63	  }
64	
65	  const log = deps.logger ?? noop;
66	  const numberedCode = numberLines(document.getText());
67	  const systemPrompt = loadPrompt(
68	    "segmentation",
69	    {
70	      language: document.languageId,
71	      filename: document.fileName,
72	      code: numberedCode,
73	    },
74	    deps.promptsDir,
75	  );
76	
77	  const baseMessages: ChatMessage[] = [{ role: "system", content: systemPrompt }];
78	
79	  let firstRaw: string | undefined;
80	  let firstFailureReason: string | undefined;
81	  try {
82	    firstRaw = await deps.adapter.complete(baseMessages, { responseFormat: "json_object" });
83	    return finalize(parseAndValidate(firstRaw, document), document, log);
84	  } catch (firstError) {
85	    if (firstError instanceof ValidationFailure) {
86	      firstFailureReason = firstError.message;
87	    } else if (firstError instanceof MalformedResponseError) {
88	      firstFailureReason = "response was not valid JSON";
89	    } else {
90	      throw firstError;
91	    }
92	
93	    const retrySystem =
94	      systemPrompt +
95	      `\n\nCRITICAL: your previous response failed validation: ${firstFailureReason}. Respond with ONLY the raw JSON object matching the schema — no markdown fences, no commentary, no explanation. Begin with { and end with }.`;
96	    const retryMessages: ChatMessage[] = [{ role: "system", content: retrySystem }];
97	
98	    let secondRaw: string | undefined;
99	    try {
100	      secondRaw = await deps.adapter.complete(retryMessages, { responseFormat: "json_object" });
101	      return finalize(parseAndValidate(secondRaw, document), document, log);
102	    } catch (secondError) {
103	      throw new MalformedResponseError(
104	        `LLM did not return valid segment JSON after retry. First failure: ${firstFailureReason}. Second failure: ${(secondError as Error).message ?? String(secondError)}`,
105	        JSON.stringify({ first: firstRaw, second: secondRaw ?? "<no response>" }),
106	      );
107	    }
108	  }
109	}
110	
111	function numberLines(text: string): string {
112	  return text.split("\n").map((line, i) => `${i + 1}: ${line}`).join("\n");
113	}
114	
115	function parseAndValidate(raw: string, document: vscode.TextDocument): ParseResult {
116	  let parsed: unknown;
117	  try {
118	    parsed = JSON.parse(raw);
119	  } catch {
120	    throw new ValidationFailure("response is not valid JSON");
121	  }
122	  if (
123	    !parsed ||
124	    typeof parsed !== "object" ||
125	    !Array.isArray((parsed as { segments?: unknown }).segments)
126	  ) {
127	    throw new ValidationFailure("response does not contain a 'segments' array");
128	  }
129	
130	  const rawSegments = (parsed as { segments: RawSegment[] }).segments;
131	  const lineCount = document.lineCount;
132	  const validated: ValidatedSegment[] = [];
133	  let droppedCount = 0;
134	
135	  for (const r of rawSegments) {
136	    const startLine = Number(r.startLine);
137	    let endLine = Number(r.endLine);
138	    const label = typeof r.label === "string" ? r.label.trim() : "";
139	    const oneLiner = typeof r.oneLiner === "string" ? r.oneLiner.trim() : "";
140	    const difficulty = typeof r.difficulty === "string" ? r.difficulty : "";
141	
142	    if (!Number.isInteger(startLine) || startLine < 1) { droppedCount++; continue; }
143	    if (!Number.isInteger(endLine)) { droppedCount++; continue; }
144	    if (endLine > lineCount) endLine = lineCount;
145	    if (endLine < startLine) { droppedCount++; continue; }
146	    if (label.length === 0 || oneLiner.length === 0) { droppedCount++; continue; }
147	    if (!VALID_DIFFICULTIES.has(difficulty as Difficulty)) { droppedCount++; continue; }
148	
149	    validated.push({ label, oneLiner, startLine, endLine, difficulty: difficulty as Difficulty });
150	  }
151	
152	  if (validated.length === 0) {
153	    throw new ValidationFailure("no segments passed per-field validation");
154	  }
155	
156	  validated.sort((a, b) => a.startLine - b.startLine || a.endLine - b.endLine);
157	
158	  for (let i = 1; i < validated.length; i++) {
159	    const prev = validated[i - 1];
160	    const curr = validated[i];
161	    if (curr.startLine <= prev.endLine) {
162	      throw new ValidationFailure(
163	        `segments overlap: "${prev.label}" (lines ${prev.startLine}-${prev.endLine}) and "${curr.label}" (lines ${curr.startLine}-${curr.endLine})`,
164	      );
165	    }
166	  }
167	
168	  return { segments: validated, droppedCount };
169	}
170	
171	function finalize(
172	  parsed: ParseResult,
173	  document: vscode.TextDocument,
174	  log: SegmenterLogger,
175	): Segment[] {
176	  const { segments, droppedCount } = parsed;
177	  const lineCount = document.lineCount;
178	
179	  const finalized: Segment[] = segments.map((s, i) => {
180	    const range = new vscode.Range(
181	      s.startLine - 1,
182	      0,
183	      Math.min(s.endLine, lineCount) - 1,
184	      Number.MAX_SAFE_INTEGER,
185	    );
186	    return {
187	      id: `seg-${i}`,
188	      label: s.label,
189	      oneLiner: s.oneLiner,
190	      startLine: s.startLine,
191	      endLine: s.endLine,
192	      code: document.getText(range),
193	      difficulty: s.difficulty,
194	    };
195	  });
196	
197	  const coverage = computeCoverage(finalized, document);
198	  log(
199	    `[segmenter] ${finalized.length} segment(s), coverage ${(coverage * 100).toFixed(0)}%` +
200	      (droppedCount > 0 ? `, dropped ${droppedCount}` : ""),
201	  );
202	  if (coverage < MIN_COVERAGE_RATIO) {
203	    log(
204	      `[segmenter] WARN coverage below ${Math.round(MIN_COVERAGE_RATIO * 100)}% — some non-blank lines were not segmented`,
205	    );
206	  }
207	
208	  return finalized;
209	}
210	
211	function computeCoverage(segments: Segment[], document: vscode.TextDocument): number {
212	  const covered = new Set<number>();
213	  for (const s of segments) {
214	    for (let line = s.startLine; line <= s.endLine; line++) {
215	      covered.add(line);
216	    }
217	  }
218	  let nonBlankTotal = 0;
219	  let nonBlankCovered = 0;
220	  for (let i = 0; i < document.lineCount; i++) {
221	    if (document.lineAt(i).text.trim().length === 0) continue;
222	    nonBlankTotal++;
223	    if (covered.has(i + 1)) nonBlankCovered++;
224	  }
225	  return nonBlankTotal === 0 ? 1 : nonBlankCovered / nonBlankTotal;
226	}
227	
228	function noop(): void {
229	  /* swallow logs when no logger injected */
230	}
