import { isOllamaReachable } from "../llm/ollamaDetection";
import { FileTooLargeError, segment } from "../engine/segmenter";
import type { SegmentStore } from "../engine/segmentStore";
import {
  AuthError,
  CancelledError,
  MalformedResponseError,
  NetworkError,
