1	import * as assert from "node:assert";
2	import * as path from "node:path";
3	import { suite, test, suiteSetup } from "mocha";
4	import * as vscode from "vscode";
5	import { segment } from "../../src/engine/segmenter";
6	import { OpenAICompatibleAdapter } from "../../src/llm/openAiCompatibleAdapter";
7	import { isOllamaReachable } from "../../src/llm/ollamaDetection";
8	
9	const PROMPTS_DIR = path.join(__dirname, "../../../prompts");
10	const FIXTURES_ROOT = path.join(__dirname, "../../../test/fixtures");
11	
12	const MIN_MEAN_IOU = 0.4;
13	const MIN_COUNT_RATIO = 0.5;
14	const MAX_COUNT_RATIO = 2.0;
15	
16	interface GoldenSegment {
17	  label: string;
